 <section class="letter-types-hero"><div><span>LAYANAN WARGA</span><h1>Jenis Surat &amp; Ikon</h1><p>Kelola jenis surat, deskripsi, urutan, ikon, dan ketersediaan layanan<br>pada katalog warga.</p></div><div class="letter-types-art" aria-hidden="true"><i class="folder"></i><i class="sheet"><b></b><b></b><b></b><em>★</em></i></div></section>
 <form class="letter-types-filter" method="get" action="<?= site_url('admin/letter_types') ?>"><label class="letter-types-search"><span>⌕</span><input type="search" name="q" value="<?= html_escape($q) ?>" placeholder="Cari jenis surat..."></label><label><span>▦</span><select name="category"><option value="">Semua Kategori</option><?php foreach(array('Kependudukan','Keterangan','Kegiatan','Lainnya') as $value): ?><option value="<?= $value ?>" <?= $category===$value?'selected':'' ?>><?= $value ?></option><?php endforeach; ?></select></label><label><span>⇅</span><select name="sort"><option value="order" <?= $sort==='order'?'selected':'' ?>>Urutan Layanan</option><option value="title" <?= $sort==='title'?'selected':'' ?>>Urutan A–Z</option><option value="newest" <?= $sort==='newest'?'selected':'' ?>>Terbaru</option></select></label><label><span>●</span><select name="active"><option value="">Semua Status</option><option value="1" <?= $active==='1'?'selected':'' ?>>Aktif</option><option value="0" <?= $active==='0'?'selected':'' ?>>Nonaktif</option></select></label><button type="submit">Filter</button><a class="letter-types-add" href="<?= site_url('admin/letter_type') ?>">＋ &nbsp; Tambah Jenis Surat</a></form>
 <section class="letter-types-table"><div><table><thead><tr><th>Ikon</th><th>Jenis Surat</th><th>Kategori</th><th>Urutan</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($items as $item): ?><tr><td><?php if($item['icon_path']): ?><img class="letter-types-icon" src="<?= base_url(html_escape($item['icon_path'])) ?>" alt=""><?php else: ?><span class="admin-letter-symbol admin-letter-symbol-<?= html_escape($item['type_key']) ?>"></span><?php endif; ?></td><td><strong><?= html_escape($item['title']) ?></strong><small><?= html_escape($item['description']) ?></small></td><td><span class="letter-category <?= strtolower($item['category']) ?>">▣ &nbsp; <?= html_escape($item['category']) ?></span></td><td><span class="letter-order"><?= (int)$item['sort_order'] ?></span></td><td><span class="letter-active <?= $item['is_active']?'on':'off' ?>"><i></i><?= $item['is_active']?'Aktif':'Nonaktif' ?></span></td><td><div class="letter-type-actions"><a class="edit" href="<?= site_url('admin/letter_type/'.$item['type_key']) ?>">✎ &nbsp; Edit</a><a class="more" href="<?= site_url('admin/letter_type/'.$item['type_key']) ?>" aria-label="Menu <?= html_escape($item['title']) ?>">⋮</a></div></td></tr><?php endforeach; ?><?php if(!$items): ?><tr><td colspan="6" class="letter-types-empty">Tidak ada jenis surat yang cocok dengan pencarian atau filter.</td></tr><?php endif; ?></tbody></table></div><footer>Menampilkan <?= count($items) ?> dari <?= (int)$total ?> jenis surat</footer></section>
